func (a *MCPAdapter) PromptsGet(ctx context.Context, p *PromptsGetPayload) (*PromptsGetResult, error) {
	if !a.isInitialized(ctx) {
		return nil, loom.PermanentError("invalid_params", "Not initialized")
	}
	if p == nil || p.Name == "" {
		return nil, loom.PermanentError("invalid_params", "Missing prompt name")
	}
	a.log(ctx, "request", map[string]any{
		"method": "prompts/get",
		"name":   p.Name,
	})
	switch p.Name {
	case "code_review":
		if a.promptProvider != nil {
			if res, err := a.promptProvider.GetCodeReviewPrompt(p.Arguments); err == nil && res != nil {
				a.log(ctx, "response", map[string]any{
					"method": "prompts/get",
					"name":   p.Name,
				})
				return res, nil
			} else if err != nil {
				return nil, a.safeMCPError(err, "internal_error", "Prompt retrieval failed.")
			}
		}
		msgs := []*PromptMessage{&PromptMessage{
			Content: &MessageContent{
				Text: stringPtr("Review the provided code and suggest improvements."),
				Type: "text",
			},
			Role: "user",
		}}
		res := &PromptsGetResult{
			Description: stringPtr("Simple code review prompt"),
			Messages:    msgs,
		}
		a.log(ctx, "response", map[string]any{
			"method": "prompts/get",
			"name":   p.Name,
		})
		return res, nil
	}
	switch p.Name {
	case "contextual_prompts":
		var args map[string]any
		if len(p.Arguments) > 0 {
			if err := json.Unmarshal(p.Arguments, &args); err != nil {
				return nil, a.safeMCPError(err, "invalid_params", "Invalid prompt arguments.")
			}
		}
		if _, ok := args["context"]; !ok {
			return nil, loom.PermanentError("invalid_params", "Missing required argument: %s", "context")
		}
		if _, ok := args["task"]; !ok {
			return nil, loom.PermanentError("invalid_params", "Missing required argument: %s", "task")
		}
		if a.promptProvider == nil {
			return nil, loom.PermanentError("invalid_params", "No prompt provider configured for dynamic prompts")
		}
		res, err := a.promptProvider.GetContextualPromptsPrompt(ctx, p.Arguments)
		if err != nil {
			return nil, a.safeMCPError(err, "internal_error", "Prompt retrieval failed.")
		}
		a.log(ctx, "response", map[string]any{
			"method": "prompts/get",
			"name":   p.Name,
		})
		return res, nil
	case "figma_implementation_prompt":
		var args map[string]any
		if len(p.Arguments) > 0 {
			if err := json.Unmarshal(p.Arguments, &args); err != nil {
				return nil, a.safeMCPError(err, "invalid_params", "Invalid prompt arguments.")
			}
		}
		if _, ok := args["screen_title"]; !ok {
			return nil, loom.PermanentError("invalid_params", "Missing required argument: %s", "screen_title")
		}
		if _, ok := args["framework"]; !ok {
			return nil, loom.PermanentError("invalid_params", "Missing required argument: %s", "framework")
		}
		if _, ok := args["design_tokens_uri"]; !ok {
			return nil, loom.PermanentError("invalid_params", "Missing required argument: %s", "design_tokens_uri")
		}
		if _, ok := args["dpi_json"]; !ok {
			return nil, loom.PermanentError("invalid_params", "Missing required argument: %s", "dpi_json")
		}
		if a.promptProvider == nil {
			return nil, loom.PermanentError("invalid_params", "No prompt provider configured for dynamic prompts")
		}
		res, err := a.promptProvider.GetFigmaImplementationPromptPrompt(ctx, p.Arguments)
		if err != nil {
			return nil, a.safeMCPError(err, "internal_error", "Prompt retrieval failed.")
		}
		a.log(ctx, "response", map[string]any{
			"method": "prompts/get",
			"name":   p.Name,
		})
		return res, nil
	}
	return nil, loom.PermanentError("invalid_params", "Unknown prompt: %s", p.Name)
}

// Notifications and events stream
func (a *MCPAdapter) NotifyStatusUpdate(ctx context.Context, p *SendNotificationPayload) error {
	if !a.isInitialized(ctx) {
		return loom.PermanentError("invalid_params", "Not initialized")
	}
	if p == nil || p.Type == "" {
		return loom.PermanentError("invalid_params", "Missing notification type")
	}
	n := &mcpruntime.Notification{
		Data:    p.Data,
		Message: p.Message,
		Type:    p.Type,
	}
	a.log(ctx, "request", map[string]any{
		"message": n.Message,
		"method":  "notify_status_update",
		"type":    n.Type,
	})
	s, err := mcpruntime.EncodeJSONToString(ctx, goahttp.ResponseEncoder, n)
	if err != nil {
		return err
	}
	ev := &EventsStreamResult{Content: []*ContentItem{buildContentItem(a, s)}}
	a.PublishContext(ctx, ev)
	a.log(ctx, "response", map[string]any{
		"method": "notify_status_update",
		"type":   n.Type,
	})
	return nil
}
func (a *MCPAdapter) EventsStream(ctx context.Context, stream EventsStreamServerStream) (res *EventsStreamResult, err error) {
	if !a.isInitialized(ctx) {
		return nil, loom.PermanentError("internal_error", "Not initialized")
	}
	a.log(ctx, "request", map[string]any{
		"method":     "events/stream",
		"session_id": mcpruntime.SessionIDFromContext(ctx),
	})
	sessionID := mcpruntime.SessionIDFromContext(ctx)
	var sub mcpruntime.Subscription
	if scoped, ok := a.broadcaster.(mcpruntime.SessionBroadcaster); ok && sessionID != "" {
		sub, err = scoped.SubscribeSession(ctx, sessionID)
	} else {
		sub, err = a.broadcaster.Subscribe(ctx)
	}
	if err != nil {
		return nil, loom.PermanentError("internal_error", "Failed to subscribe to events: %v", err)
	}
	defer sub.Close()
	for {
		select {
		case <-ctx.Done():
			a.log(ctx, "response", map[string]any{
				"closed":     true,
				"method":     "events/stream",
				"reason":     ctx.Err().Error(),
				"session_id": mcpruntime.SessionIDFromContext(ctx),
			})
			return nil, ctx.Err()
		case ev, ok := <-sub.C():
			if !ok {
				a.log(ctx, "response", map[string]any{
					"closed":     true,
					"method":     "events/stream",
					"reason":     "broadcaster_closed",
					"session_id": mcpruntime.SessionIDFromContext(ctx),
				})
				return nil, nil
			}
			evt, ok := ev.(EventsStreamEvent)
			if !ok {
				a.log(ctx, "response", map[string]any{
					"dropped_event_type": fmt.Sprintf("%T", ev),
					"method":             "events/stream",
					"session_id":         mcpruntime.SessionIDFromContext(ctx),
				})
				continue
			}
			if err := stream.Send(ctx, evt); err != nil {
				return nil, loom.PermanentError("internal_error", "Failed to send event: %v", err)
			}
			a.log(ctx, "response", map[string]any{
				"event_type": fmt.Sprintf("%T", evt),
				"method":     "events/stream",
				"session_id": mcpruntime.SessionIDFromContext(ctx),
			})
		}
	}
}
